import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"The Chinese console","description":"","frontmatter":{},"headers":[],"relativePath":"manual/chinese-console.md","filePath":"manual/chinese-console.md"}'),i={name:"manual/chinese-console.md"};function o(l,e,r,h,c,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="the-chinese-console" tabindex="-1">The Chinese console <a class="header-anchor" href="#the-chinese-console" aria-label="Permalink to &quot;The Chinese console&quot;">​</a></h1><h2 id="switching" tabindex="-1">Switching <a class="header-anchor" href="#switching" aria-label="Permalink to &quot;Switching&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lang zh        everything user-facing switches, live:</span></span>
<span class="line"><span>                    shell help, all 8 wizard apps, service surfaces</span></span>
<span class="line"><span>ush&gt; lang en        back to English</span></span>
<span class="line"><span>ush&gt; lang           show the current language</span></span></code></pre></div><p>The locale is probed per call (not cached at first render), so a <code>lang zh</code> inside a long-running ush affects the very next help line</p><ul><li>including inside the shell that owns the switch.</li></ul><h2 id="what-is-translated" tabindex="-1">What is translated <a class="header-anchor" href="#what-is-translated" aria-label="Permalink to &quot;What is translated&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Mechanism</th></tr></thead><tbody><tr><td>ush built-ins</td><td>per-app i18n tables (<code>tr_()</code>)</td></tr><tr><td>the 8 merged apps</td><td>per-app i18n tables - menus, prompts, verdicts</td></tr><tr><td>the ~280 classic apps</td><td>per-app i18n tables (<code>_hint</code> + body strings)</td></tr><tr><td>L0 service lines (help -w group names, registry titles)</td><td>the l0 table (<code>etc/i18n/l0/{en,zh}.json</code>)</td></tr></tbody></table><p>A missing translation falls back to English, then to the key itself</p><ul><li>an untranslated app can never crash or print garbage; it shows the key so the gap is visible and fixable.</li></ul><h2 id="rendering" tabindex="-1">Rendering <a class="header-anchor" href="#rendering" aria-label="Permalink to &quot;Rendering&quot;">​</a></h2><p>The CJK pipeline is always compiled in: the 16x16 GB2312 font, the GBK/UTF-8 decoder chain, and the console renderer. Both the serial line and the framebuffer console render Chinese; serial encoding follows <code>serial_encoding</code> (<code>utf8</code> default, <code>gbk</code> switchable).</p><h2 id="input-the-ime" tabindex="-1">Input - the IME <a class="header-anchor" href="#input-the-ime" aria-label="Permalink to &quot;Input - the IME&quot;">​</a></h2><p>The IME composes pinyin into GB2312 zones 16-55 (level-1: the 3755 common characters) plus phrase completions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; ime             (IME status: level-1 chars, phrases)</span></span>
<span class="line"><span>ush&gt; ime -i          (interactive compose session)</span></span></code></pre></div><p>Inside a compose session: type pinyin, pick the candidate, ESC cancels. The display service exposes the same engine to programs through L1SVC (IME begin / key / end ops).</p><h2 id="the-ascii-contract" tabindex="-1">The ASCII contract <a class="header-anchor" href="#the-ascii-contract" aria-label="Permalink to &quot;The ASCII contract&quot;">​</a></h2><p>Program <em>names</em>, file paths and service-level <strong>output lines are ASCII English</strong> - they are the script-facing contract (wizards and tests probe them: <code>&quot;A/B disk: present&quot;</code>, <code>&quot;New version available.&quot;</code>). Chinese is the <em>human</em> rendering; scripts and probes keep a stable English surface in every locale.</p>`,17)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
